package main

import (
	"context"
	"errors"
	"os"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/command"
)

func main() {
	if err := Execute(); err != nil {
		os.Exit(exitCode(err))
	}
}

// exitCode maps errors to Unix-style exit codes.
//
//	0   — success
//	1   — runtime error
//	2   — usage error (invalid flags, arguments, or missing required input)
//	127 — a required external binary is missing from PATH
//	130 — interrupted (SIGINT)
func exitCode(err error) int {
	if err == nil {
		return 0
	}
	var ue *usageError
	if errors.As(err, &ue) {
		return 2
	}
	// Cobra's built-in flag/argument errors don't wrap a typed error,
	// so we fall back to message prefix detection for those.
	if isCobraUsageError(err) {
		return 2
	}
	// A missing dependency is "command not found", not a generic failure —
	// scripts and CI can tell the two apart and react differently.
	if errors.Is(err, command.ErrNotInstalled) {
		return 127
	}
	// Ctrl-C during a long operation (the ArgoCD wait, a push over SSH) must
	// look like a signal, not a failure of the thing being run.
	if errors.Is(err, context.Canceled) {
		return 130
	}
	return 1
}

// isCobraUsageError detects Cobra-generated flag and argument errors
// that should map to exit code 2. These are errors from Cobra itself,
// not from our RunE functions (which should use usageError).
func isCobraUsageError(err error) bool {
	msg := err.Error()
	prefixes := []string{
		"unknown command",
		"unknown flag",
		"unknown shorthand flag",
		"invalid argument",
		"accepts ",
		"requires ",
		"required flag(s)",
		"at least one of the flags",
	}
	for _, p := range prefixes {
		if strings.HasPrefix(msg, p) {
			return true
		}
	}
	return false
}

package main

import (
	"fmt"
	"os"

	"github.com/spf13/cobra"
)

var (
	noColorFlag   bool
	changeDirFlag string
)

var rootCmd = &cobra.Command{
	Use:           "intropy",
	Short:         "Intropy CLI",
	Long:          "intropy is the command-line interface for working with Intropy integrations.",
	Version:       version,
	SilenceUsage:  true,
	SilenceErrors: true,
	PersistentPreRunE: func(cmd *cobra.Command, args []string) error {
		if err := chdirIfRequested(); err != nil {
			return err
		}
		warnIfPreview(cmd)
		return nil
	},
}

// chdirIfRequested applies -C before any preview warning, so the warning is
// never printed for a command that then fails to start.
func chdirIfRequested() error {
	if changeDirFlag == "" {
		return nil
	}
	if err := os.Chdir(changeDirFlag); err != nil {
		return fmt.Errorf("cannot change to directory %q: %w", changeDirFlag, err)
	}
	return nil
}

func Execute() error {
	if err := rootCmd.Execute(); err != nil {
		fmt.Fprintln(rootCmd.ErrOrStderr(), "error:", err)
		return err
	}
	return nil
}

// validateOutputFlag returns a usageError if the given format is not in the
// allowed set. Use this for --output flags that accept a fixed list of formats.
func validateOutputFlag(format string, allowed ...string) error {
	for _, a := range allowed {
		if format == a {
			return nil
		}
	}
	return newUsageErrorf("invalid output format %q (allowed: %v)", format, allowed)
}

func init() {
	rootCmd.PersistentFlags().BoolVar(&noColorFlag, "no-color", false, "disable colored output")
	rootCmd.PersistentFlags().StringVarP(&changeDirFlag, "directory", "C", "", "change to directory before running the command")
	_ = rootCmd.MarkPersistentFlagDirname("directory")
}

