package main

import "github.com/spf13/cobra"

// usageRunE wraps a command's RunE so every failure cobra reports before
// RunE runs — unknown flags, missing required flags, failed flag groups —
// is a typed usageError (exit 2). Arg validators get the same treatment
// from usageArgs, so by the time RunE's own return value is seen it is
// already typed: the command wrote it.
//
// The wrapped function is installed as the root's PersistentPreRunE: cobra
// runs inherited pre-runs on every subcommand, after flag parsing but
// before required-flag validation — the one seam that covers both. A
// subcommand defining its own PersistentPreRunE must call the root's
// explicitly, since cobra runs only the innermost.
func usageRunE(run func(cmd *cobra.Command, args []string) error) func(cmd *cobra.Command, args []string) error {
	return func(cmd *cobra.Command, args []string) error {
		cmd.SetFlagErrorFunc(func(_ *cobra.Command, err error) error {
			return &usageError{err: err}
		})
		return run(cmd, args)
	}
}

